import subprocess

import pytest

from app.telemetry import ffmpeg_io
from app.telemetry.extract import extract_telemetry


@pytest.fixture(scope="module")
def plain_video(tmp_path_factory):
    """A one-second video with no DJI meta track, generated by ffmpeg."""
    path = tmp_path_factory.mktemp("plain") / "testsrc.mp4"
    subprocess.run(
        ["ffmpeg", "-v", "error", "-y", "-f", "lavfi", "-i", "testsrc=size=320x240:rate=30", "-t", "1", str(path)],
        check=True,
    )
    return path


def test_video_without_djmd_stream_reports_no_telemetry(plain_video):
    info = ffmpeg_io.probe(plain_video)
    assert ffmpeg_io.find_telemetry_stream(info) is None

    tel = extract_telemetry(plain_video)
    assert tel.meta.telemetry_available is False
    assert len(tel) == 0
    assert tel.skipped == 0
    assert tel.meta.has_gps is False
    assert (tel.meta.width, tel.meta.height) == (320, 240)
